use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let intervals = input.as_array().unwrap();
    let mut max_overlap = 0;
    let mut current_overlap = 0;

    for interval in intervals {
        let start = interval.as_array().unwrap().get(0).unwrap().as_i64().unwrap();
        let end = interval.as_array().unwrap().get(1).unwrap().as_i64().unwrap();

        if start < end {
            current_overlap += 1;
            max_overlap = max_overlap.max(current_overlap);
        } else {
            current_overlap = 0;
        }
    }

    Value::from(max_overlap)
}
